-- Showroom core schema bootstrap (Task 002)
-- Purpose:
-- - Create showroom rental management schema in parallel with legacy finance schema
-- - Add anti-overlap locking, audit/maintenance support, and RLS baseline
--
-- Key semantics chosen here (see README.md for details):
-- - reservation_windows is the source of truth for date-range locks
-- - daterange semantics use [start_date, end_date) (end exclusive)
-- - payments.amount is non-negative; refunds are represented by type = 'REFUND'

create extension if not exists pgcrypto;
create extension if not exists btree_gist;

-- =========================================================
-- Shared helper: updated_at trigger
-- =========================================================
create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

-- =========================================================
-- 1) Branches / Profiles / Access
-- =========================================================
create table if not exists public.branches (
  id uuid primary key default gen_random_uuid(),
  code text not null,
  name text not null,
  shop_domain text,
  address text,
  phone text,
  timezone text not null default 'Asia/Ho_Chi_Minh',
  currency_code text not null default 'VND',
  is_active boolean not null default true,
  created_by uuid,
  updated_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint branches_code_not_blank check (btrim(code) <> ''),
  constraint branches_name_not_blank check (btrim(name) <> ''),
  constraint branches_shop_domain_not_blank check (
    shop_domain is null or btrim(shop_domain) <> ''
  ),
  constraint branches_shop_domain_slug_check check (
    shop_domain is null or shop_domain ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'
  ),
  constraint branches_currency_code_check check (char_length(currency_code) >= 3)
);

create unique index if not exists branches_code_key on public.branches (lower(code));
create unique index if not exists branches_shop_domain_unique_ci
  on public.branches (lower(shop_domain))
  where shop_domain is not null;
create index if not exists idx_branches_is_active on public.branches (is_active);

create table if not exists public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  full_name text,
  email text,
  phone text,
  role text not null default 'staff',
  default_branch_id uuid references public.branches(id) on delete set null,
  locale text not null default 'vi',
  is_active boolean not null default true,
  invited_by uuid,
  disabled_at timestamptz,
  disabled_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint profiles_role_check check (role in ('owner_admin', 'manager', 'staff', 'accountant')),
  constraint profiles_locale_check check (locale in ('vi', 'en'))
);

create unique index if not exists profiles_email_unique_ci
  on public.profiles (lower(email))
  where email is not null;
create index if not exists idx_profiles_default_branch_id on public.profiles (default_branch_id);
create index if not exists idx_profiles_role on public.profiles (role);

create table if not exists public.profile_branch_access (
  id uuid primary key default gen_random_uuid(),
  profile_id uuid not null references public.profiles(id) on delete cascade,
  branch_id uuid not null references public.branches(id) on delete cascade,
  is_default boolean not null default false,
  created_at timestamptz not null default now()
);

create unique index if not exists profile_branch_access_profile_branch_unique
  on public.profile_branch_access (profile_id, branch_id);
create unique index if not exists profile_branch_access_single_default_unique
  on public.profile_branch_access (profile_id)
  where is_default = true;
create index if not exists idx_profile_branch_access_branch on public.profile_branch_access (branch_id);

-- =========================================================
-- 2) Settings / Opening Hours / Deposit Defaults
-- =========================================================
create table if not exists public.system_settings (
  id uuid primary key default gen_random_uuid(),
  default_locale text not null default 'vi',
  default_currency_code text not null default 'VND',
  late_fee_mode text not null default 'fixed_per_day',
  late_fee_value numeric(14,2) not null default 0,
  laundry_tracking_enabled boolean not null default true,
  site_logo_url text,
  site_logo_dark_url text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  updated_by uuid,
  constraint system_settings_default_locale_check check (default_locale in ('vi', 'en')),
  constraint system_settings_currency_code_check check (char_length(default_currency_code) >= 3),
  constraint system_settings_late_fee_mode_check check (late_fee_mode in ('fixed_per_day', 'percent_per_day')),
  constraint system_settings_late_fee_value_check check (late_fee_value >= 0)
);

-- Singleton enforcement for system settings.
create unique index if not exists idx_system_settings_singleton on public.system_settings ((true));

create table if not exists public.branch_settings (
  id uuid primary key default gen_random_uuid(),
  branch_id uuid not null references public.branches(id) on delete cascade,
  locale text,
  currency_code text,
  late_fee_mode text,
  late_fee_value numeric(14,2),
  laundry_tracking_enabled boolean,
  is_rental_module_enabled boolean not null default true,
  is_makeup_module_enabled boolean not null default true,
  overdue_reminder_threshold_hours integer,
  laundry_stuck_threshold_days integer,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  updated_by uuid,
  constraint branch_settings_locale_check check (locale is null or locale in ('vi', 'en')),
  constraint branch_settings_currency_code_check check (currency_code is null or char_length(currency_code) >= 3),
  constraint branch_settings_late_fee_mode_check check (late_fee_mode is null or late_fee_mode in ('fixed_per_day', 'percent_per_day')),
  constraint branch_settings_late_fee_value_check check (late_fee_value is null or late_fee_value >= 0),
  constraint branch_settings_overdue_threshold_check check (overdue_reminder_threshold_hours is null or overdue_reminder_threshold_hours >= 0),
  constraint branch_settings_laundry_stuck_threshold_check check (laundry_stuck_threshold_days is null or laundry_stuck_threshold_days >= 0)
);

create unique index if not exists branch_settings_branch_id_unique on public.branch_settings (branch_id);

create table if not exists public.branch_opening_hours (
  id uuid primary key default gen_random_uuid(),
  branch_id uuid not null references public.branches(id) on delete cascade,
  day_of_week integer not null,
  is_open boolean not null default true,
  open_time time,
  close_time time,
  break_start_time time,
  break_end_time time,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint branch_opening_hours_day_of_week_check check (day_of_week between 0 and 6),
  -- Keep opening-hour config internally consistent (same-day schedule only in MVP).
  constraint branch_opening_hours_time_presence_check check (
    (not is_open) or (open_time is not null and close_time is not null)
  ),
  constraint branch_opening_hours_open_close_order_check check (
    open_time is null or close_time is null or close_time > open_time
  ),
  constraint branch_opening_hours_break_order_check check (
    break_start_time is null or break_end_time is null or break_end_time > break_start_time
  )
);

create unique index if not exists branch_opening_hours_branch_day_unique
  on public.branch_opening_hours (branch_id, day_of_week);

create table if not exists public.category_deposit_defaults (
  id uuid primary key default gen_random_uuid(),
  branch_id uuid not null references public.branches(id) on delete cascade,
  category_id uuid not null,
  default_deposit_amount numeric(14,2) not null default 0,
  currency_code text not null default 'VND',
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint category_deposit_defaults_amount_check check (default_deposit_amount >= 0),
  constraint category_deposit_defaults_currency_code_check check (char_length(currency_code) >= 3)
);

create unique index if not exists category_deposit_defaults_branch_category_unique
  on public.category_deposit_defaults (branch_id, category_id);

create table if not exists public.showroom_page_templates (
  id uuid primary key default gen_random_uuid(),
  code text not null,
  page_key text not null default 'PRODUCT_HOME',
  name text not null,
  description text,
  preview_image_path text,
  template_version integer not null default 1,
  config_schema_json jsonb,
  is_active boolean not null default true,
  is_default boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint showroom_page_templates_code_not_blank check (btrim(code) <> ''),
  constraint showroom_page_templates_name_not_blank check (btrim(name) <> ''),
  constraint showroom_page_templates_page_key_check check (page_key in ('PRODUCT_HOME')),
  constraint showroom_page_templates_version_check check (template_version >= 1)
);

create unique index if not exists showroom_page_templates_code_unique
  on public.showroom_page_templates (lower(code));
create unique index if not exists showroom_page_templates_default_per_page_unique
  on public.showroom_page_templates (page_key)
  where is_default = true;
create index if not exists idx_showroom_page_templates_page_key_active
  on public.showroom_page_templates (page_key, is_active);

create table if not exists public.showroom_page_configs (
  id uuid primary key default gen_random_uuid(),
  branch_id uuid not null references public.branches(id) on delete cascade,
  locale text not null default 'vi',
  page_key text not null default 'PRODUCT_HOME',
  template_id uuid not null references public.showroom_page_templates(id) on delete restrict,
  title text,
  subtitle text,
  hero_image_path text,
  hero_config_json jsonb,
  sections_config_json jsonb,
  filters_config_json jsonb,
  seo_config_json jsonb,
  display_config_json jsonb,
  theme_config_json jsonb,
  is_active boolean not null default true,
  is_published boolean not null default true,
  created_by uuid,
  updated_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint showroom_page_configs_locale_check check (locale in ('vi', 'en')),
  constraint showroom_page_configs_page_key_check check (page_key in ('PRODUCT_HOME'))
);

create unique index if not exists showroom_page_configs_branch_locale_page_unique
  on public.showroom_page_configs (branch_id, locale, page_key);
create index if not exists idx_showroom_page_configs_branch_page_published
  on public.showroom_page_configs (branch_id, page_key, locale, is_published);
create index if not exists idx_showroom_page_configs_template_id
  on public.showroom_page_configs (template_id);

-- =========================================================
-- 3) Customers + Customer Tags
-- =========================================================
create table if not exists public.customer_tags (
  id uuid primary key default gen_random_uuid(),
  branch_id uuid not null references public.branches(id) on delete cascade,
  code text not null,
  name text not null,
  color text,
  is_system boolean not null default false,
  warn_on_order_create boolean not null default false,
  block_order_create boolean not null default false,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint customer_tags_code_not_blank check (btrim(code) <> ''),
  constraint customer_tags_name_not_blank check (btrim(name) <> '')
);

create unique index if not exists customer_tags_branch_code_unique
  on public.customer_tags (branch_id, lower(code));

create table if not exists public.customers (
  id uuid primary key default gen_random_uuid(),
  branch_id uuid not null references public.branches(id) on delete restrict,
  customer_code text,
  full_name text not null,
  phone text,
  phone_normalized text,
  social_link text,
  address text,
  note text,
  is_active boolean not null default true,
  created_by uuid,
  updated_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint customers_full_name_not_blank check (btrim(full_name) <> '')
);

create index if not exists idx_customers_branch_id on public.customers (branch_id);
create index if not exists idx_customers_phone_normalized on public.customers (phone_normalized);
create index if not exists idx_customers_full_name on public.customers (full_name);

create table if not exists public.customer_tag_assignments (
  id uuid primary key default gen_random_uuid(),
  customer_id uuid not null references public.customers(id) on delete cascade,
  tag_id uuid not null references public.customer_tags(id) on delete cascade,
  created_by uuid,
  created_at timestamptz not null default now()
);

create unique index if not exists customer_tag_assignments_unique
  on public.customer_tag_assignments (customer_id, tag_id);

-- =========================================================
-- 4) Catalog (Categories / Tags / Products / Variants / Items)
-- =========================================================
create table if not exists public.product_categories (
  id uuid primary key default gen_random_uuid(),
  branch_id uuid references public.branches(id) on delete cascade,
  code text not null,
  name text not null,
  slug text,
  sort_order integer not null default 0,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint product_categories_code_not_blank check (btrim(code) <> ''),
  constraint product_categories_name_not_blank check (btrim(name) <> '')
);

create unique index if not exists product_categories_global_code_unique
  on public.product_categories (lower(code))
  where branch_id is null;
create unique index if not exists product_categories_branch_code_unique
  on public.product_categories (branch_id, lower(code))
  where branch_id is not null;

-- category_deposit_defaults is created earlier to keep settings section grouped,
-- so attach the FK here after product_categories exists.
do $$
begin
  if not exists (
    select 1
    from pg_constraint
    where conname = 'category_deposit_defaults_category_id_fkey'
      and conrelid = 'public.category_deposit_defaults'::regclass
  ) then
    alter table public.category_deposit_defaults
      add constraint category_deposit_defaults_category_id_fkey
      foreign key (category_id)
      references public.product_categories(id)
      on delete cascade;
  end if;
end $$;

create table if not exists public.product_tags (
  id uuid primary key default gen_random_uuid(),
  branch_id uuid references public.branches(id) on delete cascade,
  code text not null,
  name text not null,
  color text,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint product_tags_code_not_blank check (btrim(code) <> ''),
  constraint product_tags_name_not_blank check (btrim(name) <> '')
);

create unique index if not exists product_tags_global_code_unique
  on public.product_tags (lower(code))
  where branch_id is null;
create unique index if not exists product_tags_branch_code_unique
  on public.product_tags (branch_id, lower(code))
  where branch_id is not null;

create table if not exists public.products (
  id uuid primary key default gen_random_uuid(),
  branch_id uuid references public.branches(id) on delete cascade,
  product_code text not null,
  name text not null,
  category_id uuid references public.product_categories(id) on delete set null,
  gender text,
  material text,
  size_chart_json jsonb,
  description text,
  cover_image_path text,
  is_active boolean not null default true,
  is_archived boolean not null default false,
  created_by uuid,
  updated_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint products_product_code_not_blank check (btrim(product_code) <> ''),
  constraint products_name_not_blank check (btrim(name) <> ''),
  constraint products_gender_check check (gender is null or gender in ('female', 'male', 'unisex', 'other'))
);

create unique index if not exists products_global_product_code_unique
  on public.products (lower(product_code))
  where branch_id is null;
create unique index if not exists products_branch_product_code_unique
  on public.products (branch_id, lower(product_code))
  where branch_id is not null;
create index if not exists idx_products_category_id on public.products (category_id);
create index if not exists idx_products_name on public.products (name);

create table if not exists public.product_tag_assignments (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references public.products(id) on delete cascade,
  tag_id uuid not null references public.product_tags(id) on delete cascade,
  created_at timestamptz not null default now()
);

create unique index if not exists product_tag_assignments_unique
  on public.product_tag_assignments (product_id, tag_id);

create table if not exists public.product_variants (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references public.products(id) on delete cascade,
  variant_code text not null,
  sku_code text,
  name text not null,
  size text,
  color text,
  attributes_json jsonb,
  default_deposit_amount numeric(14,2) not null default 0,
  price_1d numeric(14,2),
  price_3d numeric(14,2),
  price_7d numeric(14,2),
  price_per_day numeric(14,2),
  is_active boolean not null default true,
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint product_variants_variant_code_not_blank check (btrim(variant_code) <> ''),
  constraint product_variants_name_not_blank check (btrim(name) <> ''),
  constraint product_variants_default_deposit_check check (default_deposit_amount >= 0),
  constraint product_variants_price_1d_check check (price_1d is null or price_1d >= 0),
  constraint product_variants_price_3d_check check (price_3d is null or price_3d >= 0),
  constraint product_variants_price_7d_check check (price_7d is null or price_7d >= 0),
  constraint product_variants_price_per_day_check check (price_per_day is null or price_per_day >= 0)
);

create unique index if not exists product_variants_product_variant_code_unique
  on public.product_variants (product_id, lower(variant_code));
create index if not exists idx_product_variants_product_id on public.product_variants (product_id);

create table if not exists public.items (
  id uuid primary key default gen_random_uuid(),
  branch_id uuid not null references public.branches(id) on delete restrict,
  variant_id uuid not null references public.product_variants(id) on delete restrict,
  item_code text not null,
  qr_code text,
  status text not null default 'READY',
  condition_note text,
  retired_at timestamptz,
  retired_reason text,
  created_by uuid,
  updated_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint items_item_code_not_blank check (btrim(item_code) <> ''),
  constraint items_status_check check (status in ('READY', 'RESERVED', 'ON_RENT', 'LAUNDRY', 'MAINTENANCE', 'DAMAGED', 'LOST', 'RETIRED'))
);

create unique index if not exists items_branch_item_code_unique
  on public.items (branch_id, lower(item_code));
create unique index if not exists items_qr_code_unique
  on public.items (lower(qr_code))
  where qr_code is not null;
create index if not exists idx_items_variant_id on public.items (variant_id);
create index if not exists idx_items_status on public.items (status);

-- =========================================================
-- 5) Orders / Reservation Locks / Payments / Incidents / Logs
-- =========================================================
create table if not exists public.rental_orders (
  id uuid primary key default gen_random_uuid(),
  branch_id uuid not null references public.branches(id) on delete restrict,
  order_code text not null,
  order_type text not null default 'RENTAL',
  customer_id uuid not null references public.customers(id) on delete restrict,
  status text not null default 'DRAFT',
  start_date date not null,
  end_date date not null,
  pricing_mode text,
  pickup_time time,
  return_time time,
  confirmed_at timestamptz,
  picked_up_at timestamptz,
  returned_at timestamptz,
  completed_at timestamptz,
  cancelled_at timestamptz,
  cancel_reason text,
  discount_type text,
  discount_value numeric(14,2),
  discount_amount numeric(14,2) not null default 0,
  rent_amount numeric(14,2) not null default 0,
  fees_amount numeric(14,2) not null default 0,
  total_amount numeric(14,2) not null default 0,
  deposit_amount numeric(14,2) not null default 0,
  deposit_applied_amount numeric(14,2) not null default 0,
  deposit_refunded_amount numeric(14,2) not null default 0,
  currency_code text not null default 'VND',
  note text,
  internal_note text,
  created_by uuid,
  updated_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint rental_orders_order_code_not_blank check (btrim(order_code) <> ''),
  constraint rental_orders_order_type_check check (order_type in ('RENTAL', 'SALE')),
  constraint rental_orders_status_check check (status in ('DRAFT', 'RESERVED', 'CONFIRMED', 'PICKED_UP', 'RETURNED', 'DEBT', 'COMPLETED', 'CANCELLED')),
  constraint rental_orders_pricing_mode_check check (pricing_mode is null or pricing_mode in ('STANDARD', 'QUICK')),
  constraint rental_orders_date_range_check check (end_date > start_date),
  constraint rental_orders_discount_type_check check (discount_type is null or discount_type in ('amount', 'percent')),
  constraint rental_orders_discount_value_check check (discount_value is null or discount_value >= 0),
  constraint rental_orders_discount_amount_check check (discount_amount >= 0),
  constraint rental_orders_rent_amount_check check (rent_amount >= 0),
  constraint rental_orders_fees_amount_check check (fees_amount >= 0),
  constraint rental_orders_total_amount_check check (total_amount >= 0),
  constraint rental_orders_deposit_amount_check check (deposit_amount >= 0),
  constraint rental_orders_deposit_applied_amount_check check (deposit_applied_amount >= 0),
  constraint rental_orders_deposit_refunded_amount_check check (deposit_refunded_amount >= 0),
  constraint rental_orders_currency_code_check check (char_length(currency_code) >= 3)
);

create unique index if not exists rental_orders_branch_order_code_unique
  on public.rental_orders (branch_id, lower(order_code));
create index if not exists idx_rental_orders_branch_status on public.rental_orders (branch_id, status);
create index if not exists idx_rental_orders_branch_dates on public.rental_orders (branch_id, start_date, end_date);
create index if not exists idx_rental_orders_customer_id on public.rental_orders (customer_id);

create table if not exists public.rental_order_items (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references public.rental_orders(id) on delete cascade,
  item_id uuid not null references public.items(id) on delete restrict,
  product_id uuid not null references public.products(id) on delete restrict,
  variant_id uuid not null references public.product_variants(id) on delete restrict,
  item_code_snapshot text,
  product_name_snapshot text,
  variant_name_snapshot text,
  rent_plan_type text,
  rent_plan_days integer,
  rent_price numeric(14,2) not null default 0,
  deposit_override_amount numeric(14,2),
  deposit_effective_amount numeric(14,2),
  condition_out_note text,
  condition_in_note text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint rental_order_items_rent_plan_type_check check (rent_plan_type is null or rent_plan_type in ('1d', '3d', '7d', 'custom')),
  constraint rental_order_items_rent_plan_days_check check (rent_plan_days is null or rent_plan_days > 0),
  constraint rental_order_items_rent_price_check check (rent_price >= 0),
  constraint rental_order_items_deposit_override_check check (deposit_override_amount is null or deposit_override_amount >= 0),
  constraint rental_order_items_deposit_effective_check check (deposit_effective_amount is null or deposit_effective_amount >= 0)
);

create unique index if not exists rental_order_items_order_item_unique
  on public.rental_order_items (order_id, item_id);
create index if not exists idx_rental_order_items_order_id on public.rental_order_items (order_id);
create index if not exists idx_rental_order_items_item_id on public.rental_order_items (item_id);

create table if not exists public.reservation_windows (
  id uuid primary key default gen_random_uuid(),
  branch_id uuid not null references public.branches(id) on delete restrict,
  order_id uuid not null references public.rental_orders(id) on delete cascade,
  item_id uuid not null references public.items(id) on delete restrict,
  source_order_status text not null,
  start_date date not null,
  end_date date not null,
  window_range daterange generated always as (daterange(start_date, end_date, '[)')) stored,
  is_active boolean not null default true,
  released_at timestamptz,
  release_reason text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint reservation_windows_source_order_status_check check (source_order_status in ('DRAFT', 'RESERVED', 'CONFIRMED', 'PICKED_UP', 'RETURNED', 'DEBT', 'COMPLETED', 'CANCELLED')),
  constraint reservation_windows_date_range_check check (end_date > start_date)
);

create index if not exists idx_reservation_windows_order_id on public.reservation_windows (order_id);
create index if not exists idx_reservation_windows_item_id on public.reservation_windows (item_id);
create index if not exists idx_reservation_windows_branch_active on public.reservation_windows (branch_id, is_active);

-- Exclude overlapping active windows for the same item.
do $$
begin
  if not exists (
    select 1
    from pg_constraint
    where conname = 'reservation_windows_item_range_excl'
      and conrelid = 'public.reservation_windows'::regclass
  ) then
    alter table public.reservation_windows
      add constraint reservation_windows_item_range_excl
      exclude using gist (item_id with =, window_range with &&)
      where (is_active);
  end if;
end $$;

create table if not exists public.payments (
  id uuid primary key default gen_random_uuid(),
  branch_id uuid not null references public.branches(id) on delete restrict,
  order_id uuid not null references public.rental_orders(id) on delete cascade,
  customer_id uuid references public.customers(id) on delete set null,
  type text not null,
  method text not null,
  amount numeric(14,2) not null,
  currency_code text not null default 'VND',
  reason text,
  source text,
  is_import_order boolean not null default false,
  is_initial_capital boolean not null default false,
  status text not null default 'POSTED',
  note text,
  reference_code text,
  void_reason text,
  voided_at timestamptz,
  created_by uuid,
  updated_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint payments_type_check check (type in ('RENT', 'DEPOSIT', 'FEE', 'REFUND')),
  constraint payments_method_check check (method in ('CASH', 'BANK', 'MOMO')),
  constraint payments_amount_check check (amount >= 0),
  constraint payments_status_check check (status in ('POSTED', 'VOIDED')),
  constraint payments_currency_code_check check (char_length(currency_code) >= 3)
);

create index if not exists idx_payments_branch_created_at on public.payments (branch_id, created_at);
create index if not exists idx_payments_order_id on public.payments (order_id);
create index if not exists idx_payments_type on public.payments (type);
create index if not exists idx_payments_method on public.payments (method);

create table if not exists public.item_status_logs (
  id uuid primary key default gen_random_uuid(),
  branch_id uuid not null references public.branches(id) on delete restrict,
  item_id uuid not null references public.items(id) on delete cascade,
  order_id uuid references public.rental_orders(id) on delete set null,
  from_status text,
  to_status text not null,
  reason_code text,
  reason_note text,
  actor_profile_id uuid references public.profiles(id) on delete set null,
  happened_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  constraint item_status_logs_to_status_check check (to_status in ('READY', 'RESERVED', 'ON_RENT', 'LAUNDRY', 'MAINTENANCE', 'DAMAGED', 'LOST', 'RETIRED')),
  constraint item_status_logs_from_status_check check (from_status is null or from_status in ('READY', 'RESERVED', 'ON_RENT', 'LAUNDRY', 'MAINTENANCE', 'DAMAGED', 'LOST', 'RETIRED'))
);

create index if not exists idx_item_status_logs_item_happened_at on public.item_status_logs (item_id, happened_at desc);
create index if not exists idx_item_status_logs_order_id on public.item_status_logs (order_id);

create table if not exists public.incidents (
  id uuid primary key default gen_random_uuid(),
  branch_id uuid not null references public.branches(id) on delete restrict,
  order_id uuid not null references public.rental_orders(id) on delete cascade,
  order_item_id uuid references public.rental_order_items(id) on delete set null,
  item_id uuid references public.items(id) on delete set null,
  customer_id uuid references public.customers(id) on delete set null,
  type text not null,
  status text not null default 'OPEN',
  amount numeric(14,2) not null default 0,
  apply_to_deposit boolean not null default true,
  description text,
  created_by uuid,
  updated_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint incidents_type_check check (type in ('LATE', 'DAMAGE', 'LOST', 'CLEANING')),
  constraint incidents_status_check check (status in ('OPEN', 'SETTLED', 'WAIVED')),
  constraint incidents_amount_check check (amount >= 0)
);

create index if not exists idx_incidents_order_id on public.incidents (order_id);
create index if not exists idx_incidents_item_id on public.incidents (item_id);
create index if not exists idx_incidents_branch_type on public.incidents (branch_id, type);

create table if not exists public.audit_events (
  id uuid primary key default gen_random_uuid(),
  branch_id uuid references public.branches(id) on delete set null,
  actor_profile_id uuid references public.profiles(id) on delete set null,
  entity_type text not null,
  entity_id uuid,
  action text not null,
  reason text,
  before_data jsonb,
  after_data jsonb,
  meta jsonb,
  created_at timestamptz not null default now(),
  constraint audit_events_entity_type_not_blank check (btrim(entity_type) <> ''),
  constraint audit_events_action_not_blank check (btrim(action) <> '')
);

create index if not exists idx_audit_events_branch_created_at on public.audit_events (branch_id, created_at desc);
create index if not exists idx_audit_events_entity on public.audit_events (entity_type, entity_id);
create index if not exists idx_audit_events_actor on public.audit_events (actor_profile_id);

create table if not exists public.maintenance_tasks (
  id uuid primary key default gen_random_uuid(),
  branch_id uuid not null references public.branches(id) on delete restrict,
  item_id uuid not null references public.items(id) on delete restrict,
  order_id uuid references public.rental_orders(id) on delete set null,
  incident_id uuid references public.incidents(id) on delete set null,
  status text not null default 'OPEN',
  priority text not null default 'NORMAL',
  issue_type text not null,
  title text not null,
  description text,
  assigned_to_profile_id uuid references public.profiles(id) on delete set null,
  opened_at timestamptz not null default now(),
  due_at timestamptz,
  resolved_at timestamptz,
  closed_at timestamptz,
  resolution_note text,
  created_by uuid,
  updated_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint maintenance_tasks_status_check check (status in ('OPEN', 'IN_PROGRESS', 'BLOCKED', 'RESOLVED', 'CLOSED', 'CANCELLED')),
  constraint maintenance_tasks_priority_check check (priority in ('LOW', 'NORMAL', 'HIGH', 'URGENT')),
  constraint maintenance_tasks_issue_type_check check (issue_type in ('LAUNDRY', 'MAINTENANCE', 'REPAIR', 'DAMAGE')),
  constraint maintenance_tasks_title_not_blank check (btrim(title) <> '')
);

create index if not exists idx_maintenance_tasks_branch_status on public.maintenance_tasks (branch_id, status);
create index if not exists idx_maintenance_tasks_item_id on public.maintenance_tasks (item_id);
create index if not exists idx_maintenance_tasks_assigned_to on public.maintenance_tasks (assigned_to_profile_id);

-- =========================================================
-- Helper Functions for RLS (branch isolation + owner/admin checks)
-- =========================================================
create or replace function public.current_profile_id()
returns uuid
language sql
stable
security definer
set search_path = public
as $$
  select auth.uid();
$$;

create or replace function public.current_profile_role()
returns text
language sql
stable
security definer
set search_path = public
as $$
  select p.role
  from public.profiles p
  where p.id = auth.uid()
    and p.is_active = true
  limit 1;
$$;

create or replace function public.is_owner_admin()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(public.current_profile_role() = 'owner_admin', false);
$$;

create or replace function public.can_access_branch(p_branch_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select
    case
      when auth.uid() is null then false
      when p_branch_id is null then false
      when public.is_owner_admin() then true
      else exists (
        select 1
        from public.profile_branch_access pba
        where pba.profile_id = auth.uid()
          and pba.branch_id = p_branch_id
      )
      or exists (
        select 1
        from public.profiles p
        where p.id = auth.uid()
          and p.is_active = true
          and p.default_branch_id = p_branch_id
      )
    end;
$$;

create or replace function public.can_access_optional_branch(p_branch_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select case when p_branch_id is null then true else public.can_access_branch(p_branch_id) end;
$$;

create or replace function public.can_access_product(p_product_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(public.can_access_optional_branch(p.branch_id), false)
  from public.products p
  where p.id = p_product_id
  limit 1;
$$;

create or replace function public.can_access_customer(p_customer_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(public.can_access_branch(c.branch_id), false)
  from public.customers c
  where c.id = p_customer_id
  limit 1;
$$;

create or replace function public.can_access_order(p_order_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(public.can_access_branch(o.branch_id), false)
  from public.rental_orders o
  where o.id = p_order_id
  limit 1;
$$;

grant execute on function public.current_profile_id() to authenticated;
grant execute on function public.current_profile_role() to authenticated;
grant execute on function public.is_owner_admin() to authenticated;
grant execute on function public.can_access_branch(uuid) to authenticated;
grant execute on function public.can_access_optional_branch(uuid) to authenticated;
grant execute on function public.can_access_product(uuid) to authenticated;
grant execute on function public.can_access_customer(uuid) to authenticated;
grant execute on function public.can_access_order(uuid) to authenticated;

-- =========================================================
-- Updated_at triggers (tables that have updated_at)
-- =========================================================
do $$
declare
  t text;
begin
  foreach t in array array[
    'branches', 'profiles', 'system_settings', 'branch_settings', 'branch_opening_hours', 'category_deposit_defaults',
    'showroom_page_templates', 'showroom_page_configs',
    'customer_tags', 'customers', 'product_categories', 'product_tags', 'products', 'product_variants', 'items',
    'rental_orders', 'rental_order_items', 'reservation_windows', 'payments', 'incidents', 'maintenance_tasks'
  ]
  loop
    execute format('drop trigger if exists set_updated_at on public.%I', t);
    execute format('create trigger set_updated_at before update on public.%I for each row execute function public.set_updated_at()', t);
  end loop;
end $$;

