-- =========================================================
-- RLS policies: profiles / branches / settings
-- =========================================================

-- profiles: self read only; owner_admin manages writes.
-- Rationale: avoid privilege escalation via client-side update of role/default_branch_id/is_active.
 drop policy if exists profiles_select on public.profiles;
create policy profiles_select
  on public.profiles for select
  using (id = auth.uid() or public.is_owner_admin());

drop policy if exists profiles_insert on public.profiles;
create policy profiles_insert
  on public.profiles for insert
  with check (public.is_owner_admin());

drop policy if exists profiles_update on public.profiles;
create policy profiles_update
  on public.profiles for update
  using (public.is_owner_admin())
  with check (public.is_owner_admin());

drop policy if exists profiles_delete on public.profiles;
create policy profiles_delete
  on public.profiles for delete
  using (public.is_owner_admin());

-- profile_branch_access: user can read own branch access; owner_admin manages all
 drop policy if exists profile_branch_access_select on public.profile_branch_access;
create policy profile_branch_access_select
  on public.profile_branch_access for select
  using (profile_id = auth.uid() or public.is_owner_admin());

drop policy if exists profile_branch_access_insert on public.profile_branch_access;
create policy profile_branch_access_insert
  on public.profile_branch_access for insert
  with check (public.is_owner_admin());

drop policy if exists profile_branch_access_update on public.profile_branch_access;
create policy profile_branch_access_update
  on public.profile_branch_access for update
  using (public.is_owner_admin())
  with check (public.is_owner_admin());

drop policy if exists profile_branch_access_delete on public.profile_branch_access;
create policy profile_branch_access_delete
  on public.profile_branch_access for delete
  using (public.is_owner_admin());

-- branches: branch members can read accessible branches; only owner_admin writes
 drop policy if exists branches_select on public.branches;
create policy branches_select
  on public.branches for select
  using (public.can_access_branch(id));

drop policy if exists branches_insert on public.branches;
create policy branches_insert
  on public.branches for insert
  with check (public.is_owner_admin());

drop policy if exists branches_update on public.branches;
create policy branches_update
  on public.branches for update
  using (public.is_owner_admin())
  with check (public.is_owner_admin());

drop policy if exists branches_delete on public.branches;
create policy branches_delete
  on public.branches for delete
  using (public.is_owner_admin());

-- system settings: authenticated users may read; owner_admin writes
 drop policy if exists system_settings_select on public.system_settings;
create policy system_settings_select
  on public.system_settings for select
  using (auth.uid() is not null);

drop policy if exists system_settings_insert on public.system_settings;
create policy system_settings_insert
  on public.system_settings for insert
  with check (public.is_owner_admin());

drop policy if exists system_settings_update on public.system_settings;
create policy system_settings_update
  on public.system_settings for update
  using (public.is_owner_admin())
  with check (public.is_owner_admin());

drop policy if exists system_settings_delete on public.system_settings;
create policy system_settings_delete
  on public.system_settings for delete
  using (public.is_owner_admin());

-- showroom_page_templates: template registry is managed by owner_admin (settings/admin)
drop policy if exists showroom_page_templates_select on public.showroom_page_templates;
create policy showroom_page_templates_select
  on public.showroom_page_templates for select
  using (public.is_owner_admin());

drop policy if exists showroom_page_templates_insert on public.showroom_page_templates;
create policy showroom_page_templates_insert
  on public.showroom_page_templates for insert
  with check (public.is_owner_admin());

drop policy if exists showroom_page_templates_update on public.showroom_page_templates;
create policy showroom_page_templates_update
  on public.showroom_page_templates for update
  using (public.is_owner_admin())
  with check (public.is_owner_admin());

drop policy if exists showroom_page_templates_delete on public.showroom_page_templates;
create policy showroom_page_templates_delete
  on public.showroom_page_templates for delete
  using (public.is_owner_admin());

-- Branch settings/opening hours/deposit defaults: readable by branch members; writable by owner_admin
 do $$
declare
  t text;
begin
  foreach t in array array['branch_settings', 'branch_opening_hours', 'category_deposit_defaults']
  loop
    execute format('drop policy if exists branch_settings_select on public.%I', t);
    execute format('create policy branch_settings_select on public.%I for select using (public.can_access_branch(branch_id))', t);

    execute format('drop policy if exists branch_settings_insert on public.%I', t);
    execute format('create policy branch_settings_insert on public.%I for insert with check (public.is_owner_admin() and public.can_access_branch(branch_id))', t);

    execute format('drop policy if exists branch_settings_update on public.%I', t);
    execute format('create policy branch_settings_update on public.%I for update using (public.is_owner_admin() and public.can_access_branch(branch_id)) with check (public.is_owner_admin() and public.can_access_branch(branch_id))', t);

    execute format('drop policy if exists branch_settings_delete on public.%I', t);
    execute format('create policy branch_settings_delete on public.%I for delete using (public.is_owner_admin() and public.can_access_branch(branch_id))', t);
  end loop;
end $$;

-- branch_settings: manager can write policy for accessible branches.
-- keep delete owner_admin-only.
drop policy if exists branch_settings_insert on public.branch_settings;
create policy branch_settings_insert
  on public.branch_settings for insert
  with check (
    (public.is_owner_admin() or public.current_profile_role() = 'manager')
    and public.can_access_branch(branch_id)
  );

drop policy if exists branch_settings_update on public.branch_settings;
create policy branch_settings_update
  on public.branch_settings for update
  using (
    (public.is_owner_admin() or public.current_profile_role() = 'manager')
    and public.can_access_branch(branch_id)
  )
  with check (
    (public.is_owner_admin() or public.current_profile_role() = 'manager')
    and public.can_access_branch(branch_id)
  );

-- showroom_page_configs: admin-managed config/publish for customer showroom page by branch/locale
-- Public customer page should read published config via server layer (not direct anon Data API in MVP).
drop policy if exists showroom_page_configs_select on public.showroom_page_configs;
create policy showroom_page_configs_select
  on public.showroom_page_configs for select
  using (public.is_owner_admin() and public.can_access_branch(branch_id));

drop policy if exists showroom_page_configs_insert on public.showroom_page_configs;
create policy showroom_page_configs_insert
  on public.showroom_page_configs for insert
  with check (public.is_owner_admin() and public.can_access_branch(branch_id));

drop policy if exists showroom_page_configs_update on public.showroom_page_configs;
create policy showroom_page_configs_update
  on public.showroom_page_configs for update
  using (public.is_owner_admin() and public.can_access_branch(branch_id))
  with check (public.is_owner_admin() and public.can_access_branch(branch_id));

drop policy if exists showroom_page_configs_delete on public.showroom_page_configs;
create policy showroom_page_configs_delete
  on public.showroom_page_configs for delete
  using (public.is_owner_admin() and public.can_access_branch(branch_id));

-- =========================================================
-- RLS policies: branch-scoped direct tables
-- =========================================================
 do $$
declare
  t text;
begin
  foreach t in array array[
    'customer_tags', 'customers', 'items', 'rental_orders', 'reservation_windows',
    'payments', 'incidents', 'maintenance_tasks'
  ]
  loop
    execute format('drop policy if exists branch_select on public.%I', t);
    execute format('create policy branch_select on public.%I for select using (public.can_access_branch(branch_id))', t);

    execute format('drop policy if exists branch_insert on public.%I', t);
    execute format('create policy branch_insert on public.%I for insert with check (public.can_access_branch(branch_id))', t);

    execute format('drop policy if exists branch_update on public.%I', t);
    execute format('create policy branch_update on public.%I for update using (public.can_access_branch(branch_id)) with check (public.can_access_branch(branch_id))', t);

    execute format('drop policy if exists branch_delete on public.%I', t);
    execute format('create policy branch_delete on public.%I for delete using (public.can_access_branch(branch_id))', t);
  end loop;
end $$;

-- item_status_logs: append-only operational log (read + insert only)
drop policy if exists item_status_logs_select on public.item_status_logs;
create policy item_status_logs_select
  on public.item_status_logs for select
  using (public.can_access_branch(branch_id));

drop policy if exists item_status_logs_insert on public.item_status_logs;
create policy item_status_logs_insert
  on public.item_status_logs for insert
  with check (public.can_access_branch(branch_id));

drop policy if exists item_status_logs_update on public.item_status_logs;
drop policy if exists item_status_logs_delete on public.item_status_logs;

-- product categories/tags/products support optional branch scope (global rows allowed)
 do $$
declare
  t text;
begin
  foreach t in array array['product_categories', 'product_tags', 'products']
  loop
    execute format('drop policy if exists optional_branch_select on public.%I', t);
    execute format('create policy optional_branch_select on public.%I for select using (public.can_access_optional_branch(branch_id))', t);

    execute format('drop policy if exists optional_branch_insert on public.%I', t);
    execute format(
      'create policy optional_branch_insert on public.%I for insert with check ((branch_id is null and public.is_owner_admin()) or (branch_id is not null and public.can_access_branch(branch_id)))',
      t
    );

    execute format('drop policy if exists optional_branch_update on public.%I', t);
    execute format(
      'create policy optional_branch_update on public.%I for update using ((branch_id is null and public.is_owner_admin()) or (branch_id is not null and public.can_access_branch(branch_id))) with check ((branch_id is null and public.is_owner_admin()) or (branch_id is not null and public.can_access_branch(branch_id)))',
      t
    );

    execute format('drop policy if exists optional_branch_delete on public.%I', t);
    execute format(
      'create policy optional_branch_delete on public.%I for delete using ((branch_id is null and public.is_owner_admin()) or (branch_id is not null and public.can_access_branch(branch_id)))',
      t
    );
  end loop;
end $$;

-- Tables whose access derives from product
 do $$
declare
  t text;
begin
  foreach t in array array['product_variants', 'product_tag_assignments']
  loop
    execute format('drop policy if exists product_scope_select on public.%I', t);
    execute format('create policy product_scope_select on public.%I for select using (public.can_access_product(product_id))', t);

    execute format('drop policy if exists product_scope_insert on public.%I', t);
    execute format('create policy product_scope_insert on public.%I for insert with check (public.can_access_product(product_id))', t);

    execute format('drop policy if exists product_scope_update on public.%I', t);
    execute format('create policy product_scope_update on public.%I for update using (public.can_access_product(product_id)) with check (public.can_access_product(product_id))', t);

    execute format('drop policy if exists product_scope_delete on public.%I', t);
    execute format('create policy product_scope_delete on public.%I for delete using (public.can_access_product(product_id))', t);
  end loop;
end $$;

-- customer_tag_assignments derives access from customer row
 drop policy if exists customer_assignment_select on public.customer_tag_assignments;
create policy customer_assignment_select
  on public.customer_tag_assignments for select
  using (public.can_access_customer(customer_id));

drop policy if exists customer_assignment_insert on public.customer_tag_assignments;
create policy customer_assignment_insert
  on public.customer_tag_assignments for insert
  with check (public.can_access_customer(customer_id));

drop policy if exists customer_assignment_update on public.customer_tag_assignments;
create policy customer_assignment_update
  on public.customer_tag_assignments for update
  using (public.can_access_customer(customer_id))
  with check (public.can_access_customer(customer_id));

drop policy if exists customer_assignment_delete on public.customer_tag_assignments;
create policy customer_assignment_delete
  on public.customer_tag_assignments for delete
  using (public.can_access_customer(customer_id));

-- rental_order_items derives access from order row
 drop policy if exists rental_order_items_select on public.rental_order_items;
create policy rental_order_items_select
  on public.rental_order_items for select
  using (public.can_access_order(order_id));

drop policy if exists rental_order_items_insert on public.rental_order_items;
create policy rental_order_items_insert
  on public.rental_order_items for insert
  with check (public.can_access_order(order_id));

drop policy if exists rental_order_items_update on public.rental_order_items;
create policy rental_order_items_update
  on public.rental_order_items for update
  using (public.can_access_order(order_id))
  with check (public.can_access_order(order_id));

drop policy if exists rental_order_items_delete on public.rental_order_items;
create policy rental_order_items_delete
  on public.rental_order_items for delete
  using (public.can_access_order(order_id));

-- audit_events: branch rows follow branch access; null branch rows are owner_admin-only
 drop policy if exists audit_events_select on public.audit_events;
create policy audit_events_select
  on public.audit_events for select
  using (
    (branch_id is null and public.is_owner_admin()) or
    (branch_id is not null and public.can_access_branch(branch_id))
  );

drop policy if exists audit_events_insert on public.audit_events;
create policy audit_events_insert
  on public.audit_events for insert
  with check (
    (branch_id is null and public.is_owner_admin()) or
    (branch_id is not null and public.can_access_branch(branch_id))
  );

drop policy if exists audit_events_update on public.audit_events;
create policy audit_events_update
  on public.audit_events for update
  using (public.is_owner_admin())
  with check (public.is_owner_admin());

drop policy if exists audit_events_delete on public.audit_events;
create policy audit_events_delete
  on public.audit_events for delete
  using (public.is_owner_admin());

-- =========================================================
-- Grants (RLS still applies)
-- =========================================================
grant usage on schema public to authenticated, service_role;

do $$
declare
  t text;
begin
  foreach t in array array[
    'branches', 'profiles', 'profile_branch_access',
    'system_settings', 'branch_settings', 'branch_opening_hours', 'category_deposit_defaults',
    'showroom_page_templates', 'showroom_page_configs',
    'customer_tags', 'customers', 'customer_tag_assignments',
    'product_categories', 'product_tags', 'products', 'product_tag_assignments', 'product_variants',
    'items', 'rental_orders', 'rental_order_items', 'reservation_windows',
    'payments', 'item_status_logs', 'incidents', 'audit_events', 'maintenance_tasks'
  ]
  loop
    execute format(
      'grant select, insert, update, delete on table public.%I to authenticated, service_role',
      t
    );
  end loop;
end $$;

-- Service-role is used by server-side APIs; it must have table/function/sequence privileges.
-- RLS bypass for service_role is managed by Supabase role attributes, not by these grants.
grant all on all tables in schema public to service_role;
grant all on all sequences in schema public to service_role;
grant execute on all functions in schema public to service_role;

-- Keep future objects accessible for service-role when setup is rerun from scratch.
alter default privileges in schema public grant all on tables to service_role;
alter default privileges in schema public grant all on sequences to service_role;
alter default privileges in schema public grant execute on functions to service_role;

-- <<< END 002_showroom_core_schema.sql

-- >>> BEGIN 004_release_hardening.sql

-- Release hardening supplement (Task 017)
-- Scope:
-- 1) lock append-only logs against UPDATE/DELETE
-- 2) tighten RLS/policy surface for audit_events
-- 3) revoke UPDATE/DELETE grants on append-only tables

create or replace function public.block_append_only_mutation()
returns trigger
language plpgsql
as $$
begin
  raise exception '% is append-only; update/delete is forbidden', tg_table_name
    using errcode = '42501';
end;
$$;

drop trigger if exists audit_events_append_only_guard on public.audit_events;
create trigger audit_events_append_only_guard
  before update or delete on public.audit_events
  for each row execute function public.block_append_only_mutation();

drop trigger if exists item_status_logs_append_only_guard on public.item_status_logs;
create trigger item_status_logs_append_only_guard
  before update or delete on public.item_status_logs
