-- >>> BEGIN 005_migrate_fix_bug_auth_password_login_500.sql

-- 005_migrate_fix_bug_auth_password_login_500.sql
-- Fix for Supabase password login returning 500 unexpected_failure
-- message: "Database error querying schema"
--
-- Root cause observed in this project:
-- some token-like columns in auth.users can be NULL after manual SQL seed,
-- while GoTrue password flow expects text values.
--
-- This migration is idempotent and does NOT change existing SQL files.

begin;

do $$
declare
  v_rows bigint;
  v_total bigint := 0;
begin
  if exists (
    select 1
    from information_schema.columns
    where table_schema = 'auth'
      and table_name = 'users'
      and column_name = 'confirmation_token'
  ) then
    update auth.users
    set confirmation_token = ''
    where confirmation_token is null;
    get diagnostics v_rows = row_count;
    v_total := v_total + v_rows;
  end if;

  if exists (
    select 1
    from information_schema.columns
    where table_schema = 'auth'
      and table_name = 'users'
      and column_name = 'email_change'
  ) then
    update auth.users
    set email_change = ''
    where email_change is null;
    get diagnostics v_rows = row_count;
    v_total := v_total + v_rows;
  end if;

  if exists (
    select 1
    from information_schema.columns
    where table_schema = 'auth'
      and table_name = 'users'
      and column_name = 'email_change_token_new'
  ) then
    update auth.users
    set email_change_token_new = ''
    where email_change_token_new is null;
    get diagnostics v_rows = row_count;
    v_total := v_total + v_rows;
  end if;

  if exists (
    select 1
    from information_schema.columns
    where table_schema = 'auth'
      and table_name = 'users'
      and column_name = 'email_change_token_current'
  ) then
    update auth.users
    set email_change_token_current = ''
    where email_change_token_current is null;
    get diagnostics v_rows = row_count;
    v_total := v_total + v_rows;
  end if;

  if exists (
    select 1
    from information_schema.columns
    where table_schema = 'auth'
      and table_name = 'users'
      and column_name = 'recovery_token'
  ) then
    update auth.users
    set recovery_token = ''
    where recovery_token is null;
    get diagnostics v_rows = row_count;
    v_total := v_total + v_rows;
  end if;

  if exists (
    select 1
    from information_schema.columns
    where table_schema = 'auth'
      and table_name = 'users'
      and column_name = 'reauthentication_token'
  ) then
    update auth.users
    set reauthentication_token = ''
    where reauthentication_token is null;
    get diagnostics v_rows = row_count;
    v_total := v_total + v_rows;
  end if;

  if exists (
    select 1
    from information_schema.columns
    where table_schema = 'auth'
      and table_name = 'users'
      and column_name = 'phone_change'
  ) then
    update auth.users
    set phone_change = ''
    where phone_change is null;
    get diagnostics v_rows = row_count;
    v_total := v_total + v_rows;
  end if;

  if exists (
    select 1
    from information_schema.columns
    where table_schema = 'auth'
      and table_name = 'users'
      and column_name = 'phone_change_token'
  ) then
    update auth.users
    set phone_change_token = ''
    where phone_change_token is null;
    get diagnostics v_rows = row_count;
    v_total := v_total + v_rows;
  end if;

  if exists (
    select 1
    from information_schema.columns
    where table_schema = 'auth'
      and table_name = 'users'
      and column_name = 'updated_at'
  ) then
    update auth.users
    set updated_at = now()
    where lower(email) = lower('admin@kata.com');
  end if;

  raise notice 'auth.users token-null fix applied. rows updated=%', v_total;
end $$;

commit;

-- <<< END 005_migrate_fix_bug_auth_password_login_500.sql

