-- =========================================================
-- 006_notifications_module.sql
-- In-app notifications (MVP): table + indexes + RLS + realtime publication
-- =========================================================

create table if not exists public.notifications (
  id uuid primary key default gen_random_uuid(),
  recipient_profile_id uuid not null references public.profiles(id) on delete cascade,
  branch_id uuid references public.branches(id) on delete set null,
  type text not null,
  severity text not null default 'info',
  title text not null,
  body text not null,
  payload_json jsonb not null default '{}'::jsonb,
  event_key text,
  is_read boolean not null default false,
  read_at timestamptz,
  created_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint notifications_type_not_blank check (btrim(type) <> ''),
  constraint notifications_title_not_blank check (btrim(title) <> ''),
  constraint notifications_body_not_blank check (btrim(body) <> ''),
  constraint notifications_severity_check check (severity in ('info', 'success', 'warning', 'error'))
);

create index if not exists idx_notifications_recipient_created_at
  on public.notifications (recipient_profile_id, created_at desc);

create index if not exists idx_notifications_recipient_unread
  on public.notifications (recipient_profile_id, is_read, created_at desc);

create index if not exists idx_notifications_branch_created_at
  on public.notifications (branch_id, created_at desc);

create unique index if not exists notifications_recipient_event_key_unique
  on public.notifications (recipient_profile_id, event_key)
  where event_key is not null;

-- keep updated_at aligned with existing schema trigger helper
drop trigger if exists set_updated_at on public.notifications;
create trigger set_updated_at
  before update on public.notifications
  for each row
  execute function public.set_updated_at();

alter table public.notifications enable row level security;

drop policy if exists notifications_select on public.notifications;
create policy notifications_select
  on public.notifications for select
  using (recipient_profile_id = public.current_profile_id());

drop policy if exists notifications_update on public.notifications;
create policy notifications_update
  on public.notifications for update
  using (recipient_profile_id = public.current_profile_id())
  with check (recipient_profile_id = public.current_profile_id());

-- authenticated users can read/update their own notifications only
-- inserts are service-role driven (fanout side-effects from backend)
grant select, update on public.notifications to authenticated;

-- enable realtime streaming for client subscription
-- duplicate/add-table errors are ignored for rerunnable migration behavior
DO $$
BEGIN
  ALTER PUBLICATION supabase_realtime ADD TABLE public.notifications;
EXCEPTION
  WHEN duplicate_object THEN
    NULL;
  WHEN undefined_object THEN
    NULL;
  WHEN invalid_parameter_value THEN
    NULL;
END $$;

-- <<< END 006_notifications_module.sql

