create table if not exists public.sales_shifts (
  id uuid primary key default gen_random_uuid(),
  branch_id uuid not null references public.branches(id) on delete restrict,
  opened_by uuid not null references public.profiles(id) on delete restrict,
  opened_at timestamptz not null default now(),
  opening_cash numeric(12,2) not null default 0,
  status text not null default 'OPEN',
  closed_by uuid references public.profiles(id) on delete set null,
  closed_at timestamptz,
  closing_cash numeric(12,2),
  note text,
  created_by uuid references public.profiles(id) on delete set null,
  updated_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint sales_shifts_status_check check (status in ('OPEN', 'CLOSED')),
  constraint sales_shifts_opening_cash_non_negative check (opening_cash >= 0),
  constraint sales_shifts_closing_cash_non_negative check (closing_cash is null or closing_cash >= 0),
  constraint sales_shifts_closed_payload_check check (
    (status = 'OPEN' and closed_at is null and closed_by is null and closing_cash is null)
    or
    (status = 'CLOSED' and closed_at is not null and closed_by is not null and closing_cash is not null)
  )
);

create index if not exists idx_sales_shifts_branch_opened_at
