  on public.sales_shifts for select
  using (public.can_access_branch(branch_id));

drop policy if exists sales_shifts_insert on public.sales_shifts;
create policy sales_shifts_insert
  on public.sales_shifts for insert
  with check (
    public.can_access_branch(branch_id)
    and opened_by = public.current_profile_id()
  );

drop policy if exists sales_shifts_update on public.sales_shifts;
create policy sales_shifts_update
  on public.sales_shifts for update
  using (
    public.can_access_branch(branch_id)
    and opened_by = public.current_profile_id()
  )
  with check (
    public.can_access_branch(branch_id)
    and opened_by = public.current_profile_id()
  );

grant select, insert, update on public.sales_shifts to authenticated;

