-- Task 037: add `customer` role for self-signup users and role-based routing.

-- Keep legacy/custom role values safe before enforcing the new check constraint.
update public.profiles
set role = case
  when lower(coalesce(role, '')) = 'admin' then 'owner_admin'
  when lower(coalesce(role, '')) in ('owner_admin', 'manager', 'staff', 'accountant', 'customer') then lower(role)
  else 'customer'
end;

alter table if exists public.profiles
  alter column role set default 'customer';

-- Recreate role constraint with `customer` included (idempotent).
do $$
begin
  if exists (
    select 1
    from pg_constraint
    where conname = 'profiles_role_check'
      and conrelid = 'public.profiles'::regclass
  ) then
    alter table public.profiles
      drop constraint profiles_role_check;
  end if;

  alter table public.profiles
    add constraint profiles_role_check
    check (role in ('owner_admin', 'manager', 'staff', 'accountant', 'customer'));
end $$;

