-- =========================================================
-- 010_showrooms_slug_routing.sql
-- Purpose:
-- - Add showroom registry table for admin CRUD and public slug routing
-- - Seed a default showroom (if missing) for /{locale}/showroom fallback
-- =========================================================

create table if not exists public.showrooms (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  slug text not null,
  branch_id uuid not null references public.branches(id) on delete restrict,
  is_default boolean not null default false,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  created_by uuid references public.profiles(id) on delete set null,
  updated_by uuid references public.profiles(id) on delete set null,
  constraint showrooms_name_not_blank check (btrim(name) <> ''),
  constraint showrooms_slug_not_blank check (btrim(slug) <> ''),
  constraint showrooms_slug_format check (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$')
);

create unique index if not exists showrooms_slug_unique_ci
  on public.showrooms (lower(slug));
create unique index if not exists showrooms_single_default_unique
  on public.showrooms ((is_default))
  where is_default;
create index if not exists idx_showrooms_branch_active
  on public.showrooms (branch_id, is_active);
create index if not exists idx_showrooms_default_active
  on public.showrooms (is_default, is_active);

-- keep updated_at auto-maintained
drop trigger if exists set_updated_at on public.showrooms;
create trigger set_updated_at
before update on public.showrooms
for each row execute function public.set_updated_at();

alter table public.showrooms enable row level security;

drop policy if exists showrooms_select on public.showrooms;
create policy showrooms_select
  on public.showrooms for select
  using (public.is_owner_admin() and public.can_access_branch(branch_id));

drop policy if exists showrooms_insert on public.showrooms;
create policy showrooms_insert
  on public.showrooms for insert
  with check (public.is_owner_admin() and public.can_access_branch(branch_id));

drop policy if exists showrooms_update on public.showrooms;
create policy showrooms_update
  on public.showrooms for update
  using (public.is_owner_admin() and public.can_access_branch(branch_id))
  with check (public.is_owner_admin() and public.can_access_branch(branch_id));

drop policy if exists showrooms_delete on public.showrooms;
create policy showrooms_delete
  on public.showrooms for delete
  using (public.is_owner_admin() and public.can_access_branch(branch_id));

grant select, insert, update, delete on table public.showrooms to authenticated;

do $$
declare
  v_branch_id uuid;
  v_slug text := 'showroom-mac-dinh';
begin
  select b.id
    into v_branch_id
  from public.branches b
  where b.is_active = true
  order by b.code asc
  limit 1;

  if v_branch_id is null then
    return;
  end if;

  if exists(select 1 from public.showrooms where is_default = true) then
    return;
  end if;

  if exists(select 1 from public.showrooms where lower(slug) = lower(v_slug)) then
    v_slug := v_slug || '-' || substr(replace(v_branch_id::text, '-', ''), 1, 8);
  end if;

  insert into public.showrooms (
    name,
    slug,
    branch_id,
    is_default,
    is_active
  )
  values (
    'Showroom mặc định',
    v_slug,
    v_branch_id,
    true,
    true
  );
end $$;

-- <<< END 010_showrooms_slug_routing.sql

-- >>> BEGIN 011_products_pricing_stock_and_rent_metrics.sql

-- Task 039: add product-level pricing/cost flags and successful rent count metric.

alter table if exists public.products
  add column if not exists rent_price_per_day numeric(14,2);

alter table if exists public.products
  add column if not exists quick_rent_price numeric(14,2);

alter table if exists public.products
  add column if not exists sale_price numeric(14,2);

alter table if exists public.products
  add column if not exists purchase_price numeric(14,2);

alter table if exists public.products
  add column if not exists successful_rent_count integer not null default 0;

alter table if exists public.products
  add column if not exists is_rentable boolean not null default true;

alter table if exists public.products
  add column if not exists is_saleable boolean not null default false;

update public.products
set successful_rent_count = 0
where successful_rent_count is null;

update public.products
set is_rentable = true
where is_rentable is null;

update public.products
set is_saleable = false
where is_saleable is null;

do $$
begin
  if not exists (
    select 1
    from pg_constraint
    where conname = 'products_rent_price_per_day_check'
  ) then
    alter table public.products
      add constraint products_rent_price_per_day_check
      check (rent_price_per_day is null or rent_price_per_day >= 0);
  end if;

  if not exists (
    select 1
    from pg_constraint
    where conname = 'products_quick_rent_price_check'
  ) then
    alter table public.products
      add constraint products_quick_rent_price_check
      check (quick_rent_price is null or quick_rent_price >= 0);
  end if;

  if not exists (
    select 1
    from pg_constraint
    where conname = 'products_sale_price_check'
  ) then
    alter table public.products
      add constraint products_sale_price_check
      check (sale_price is null or sale_price >= 0);
  end if;

  if not exists (
    select 1
    from pg_constraint
    where conname = 'products_purchase_price_check'
  ) then
    alter table public.products
      add constraint products_purchase_price_check
      check (purchase_price is null or purchase_price >= 0);
  end if;

  if not exists (
    select 1
    from pg_constraint
    where conname = 'products_successful_rent_count_check'
  ) then
    alter table public.products
      add constraint products_successful_rent_count_check
      check (successful_rent_count >= 0);
  end if;
end $$;

create or replace function public.sync_products_successful_rent_count_by_product_ids(
  p_product_ids uuid[]
)
returns void
language plpgsql
as $$
declare
  v_product_ids uuid[];
begin
  select coalesce(array_agg(distinct product_id), '{}'::uuid[])
    into v_product_ids
  from unnest(coalesce(p_product_ids, '{}'::uuid[])) as t(product_id)
  where product_id is not null;

  if cardinality(v_product_ids) = 0 then
    return;
  end if;

  with counts as (
    select
      pv.product_id,
      count(distinct roi.order_id)::integer as successful_rent_count
    from public.rental_order_items roi
    join public.rental_orders ro
      on ro.id = roi.order_id
     and ro.status = 'COMPLETED'
    join public.items i
      on i.id = roi.item_id
    join public.product_variants pv
      on pv.id = i.variant_id
    where pv.product_id = any(v_product_ids)
    group by pv.product_id
  )
  update public.products p
  set successful_rent_count = coalesce(counts.successful_rent_count, 0)
  from (
    select product_id from unnest(v_product_ids) as u(product_id)
  ) touched
  left join counts
    on counts.product_id = touched.product_id
  where p.id = touched.product_id;
end;
$$;

create or replace function public.sync_products_successful_rent_count_from_orders()
returns trigger
language plpgsql
as $$
declare
  v_product_ids uuid[];
begin
  if tg_op = 'UPDATE'
     and old.status is distinct from new.status
     and (old.status = 'COMPLETED' or new.status = 'COMPLETED') then
    select coalesce(array_agg(distinct pv.product_id), '{}'::uuid[])
      into v_product_ids
    from public.rental_order_items roi
    join public.items i
      on i.id = roi.item_id
    join public.product_variants pv
      on pv.id = i.variant_id
    where roi.order_id = new.id;

    perform public.sync_products_successful_rent_count_by_product_ids(v_product_ids);
  end if;

  return null;
end;
$$;

create or replace function public.sync_products_successful_rent_count_from_order_items()
returns trigger
language plpgsql
as $$
declare
  v_item_ids uuid[] := '{}'::uuid[];
  v_product_ids uuid[];
begin
  if tg_op = 'INSERT' then
    v_item_ids := array_append(v_item_ids, new.item_id);
  elsif tg_op = 'DELETE' then
    v_item_ids := array_append(v_item_ids, old.item_id);
  else
    v_item_ids := array_append(v_item_ids, new.item_id);
    v_item_ids := array_append(v_item_ids, old.item_id);
  end if;

  select coalesce(array_agg(distinct pv.product_id), '{}'::uuid[])
    into v_product_ids
  from public.items i
  join public.product_variants pv
    on pv.id = i.variant_id
  where i.id = any(v_item_ids);

  perform public.sync_products_successful_rent_count_by_product_ids(v_product_ids);
  return null;
end;
$$;

drop trigger if exists trg_products_successful_rent_count_on_orders on public.rental_orders;
create trigger trg_products_successful_rent_count_on_orders
after update of status on public.rental_orders
for each row execute function public.sync_products_successful_rent_count_from_orders();

drop trigger if exists trg_products_successful_rent_count_on_order_items on public.rental_order_items;
create trigger trg_products_successful_rent_count_on_order_items
after insert or update or delete on public.rental_order_items
for each row execute function public.sync_products_successful_rent_count_from_order_items();

with counts as (
  select
    pv.product_id,
    count(distinct roi.order_id)::integer as successful_rent_count
  from public.rental_order_items roi
  join public.rental_orders ro
    on ro.id = roi.order_id
   and ro.status = 'COMPLETED'
  join public.items i
    on i.id = roi.item_id
  join public.product_variants pv
    on pv.id = i.variant_id
  group by pv.product_id
)
update public.products p
set successful_rent_count = coalesce(counts.successful_rent_count, 0)
from counts
where p.id = counts.product_id;

update public.products p
set successful_rent_count = 0
where not exists (
  select 1
  from public.rental_order_items roi
  join public.rental_orders ro
    on ro.id = roi.order_id
   and ro.status = 'COMPLETED'
  join public.items i
    on i.id = roi.item_id
  join public.product_variants pv
    on pv.id = i.variant_id
  where pv.product_id = p.id
);

-- <<< END 011_products_pricing_stock_and_rent_metrics.sql

