-- >>> BEGIN 014_remove_variant_relations_cutover.sql

-- Task 042 (phase-2 cutover): remove variant relations and normalize item/order linkage to product-level.
-- IMPORTANT:
-- - This migration is destructive for variant schema (`product_variants`, `variant_id`, `variant_name_snapshot`).
-- - Run only when application/runtime code has fully migrated away from variant-based reads/writes.

-- 1) Add product-level relation directly on items.
alter table if exists public.items
  add column if not exists product_id uuid;

-- 2) Backfill items.product_id from product_variants (if table still exists).
do $$
begin
  if exists (
    select 1
    from information_schema.tables
    where table_schema = 'public'
      and table_name = 'product_variants'
  ) then
    update public.items i
    set product_id = pv.product_id
    from public.product_variants pv
    where i.variant_id = pv.id
      and i.product_id is null;
  end if;
end $$;

-- Fallback backfill from rental_order_items snapshot if any row is still null.
update public.items i
set product_id = source.product_id
from (
  select roi.item_id, max(roi.product_id::text)::uuid as product_id
  from public.rental_order_items roi
  where roi.product_id is not null
  group by roi.item_id
) as source
where i.id = source.item_id
  and i.product_id is null;

-- 3) Add FK/index for items.product_id.
do $$
begin
  if not exists (
    select 1
    from pg_constraint
    where conname = 'items_product_id_fkey'
      and conrelid = 'public.items'::regclass
  ) then
    alter table public.items
      add constraint items_product_id_fkey
      foreign key (product_id) references public.products(id) on delete restrict;
  end if;
end $$;

create index if not exists idx_items_product_id on public.items (product_id);

-- 4) Enforce NOT NULL only when data is fully backfilled.
do $$
begin
  if exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'items'
      and column_name = 'product_id'
      and is_nullable = 'YES'
  ) then
    if not exists (select 1 from public.items where product_id is null) then
      alter table public.items
        alter column product_id set not null;
    end if;
  end if;
end $$;

-- 5) Keep rental_order_items.product_id synchronized with items.product_id.
update public.rental_order_items roi
set product_id = i.product_id
from public.items i
where roi.item_id = i.id
  and i.product_id is not null
  and roi.product_id is distinct from i.product_id;

-- 6) Rebuild successful_rent_count sync functions to use product_id directly (no product_variants join).
create or replace function public.sync_products_successful_rent_count_by_product_ids(
  p_product_ids uuid[]
)
returns void
language plpgsql
as $$
declare
  v_product_ids uuid[];
begin
  select coalesce(array_agg(distinct product_id), '{}'::uuid[])
    into v_product_ids
  from unnest(coalesce(p_product_ids, '{}'::uuid[])) as t(product_id)
  where product_id is not null;

  if cardinality(v_product_ids) = 0 then
    return;
  end if;

  with counts as (
    select
      roi.product_id,
      count(distinct roi.order_id)::integer as successful_rent_count
    from public.rental_order_items roi
    join public.rental_orders ro
      on ro.id = roi.order_id
     and ro.status = 'COMPLETED'
    where roi.product_id = any(v_product_ids)
    group by roi.product_id
  )
  update public.products p
  set successful_rent_count = coalesce(counts.successful_rent_count, 0)
  from (
    select product_id from unnest(v_product_ids) as u(product_id)
  ) touched
  left join counts
    on counts.product_id = touched.product_id
  where p.id = touched.product_id;
end;
$$;

create or replace function public.sync_products_successful_rent_count_from_orders()
returns trigger
language plpgsql
as $$
declare
  v_product_ids uuid[];
begin
  if tg_op = 'UPDATE'
     and old.status is distinct from new.status
     and (old.status = 'COMPLETED' or new.status = 'COMPLETED') then
    select coalesce(array_agg(distinct roi.product_id), '{}'::uuid[])
      into v_product_ids
    from public.rental_order_items roi
    where roi.order_id = new.id
      and roi.product_id is not null;

    perform public.sync_products_successful_rent_count_by_product_ids(v_product_ids);
  end if;

  return null;
end;
$$;

create or replace function public.sync_products_successful_rent_count_from_order_items()
returns trigger
language plpgsql
as $$
declare
  v_product_ids uuid[] := '{}'::uuid[];
begin
  if tg_op = 'INSERT' then
    v_product_ids := array_append(v_product_ids, new.product_id);
  elsif tg_op = 'DELETE' then
    v_product_ids := array_append(v_product_ids, old.product_id);
  else
    v_product_ids := array_append(v_product_ids, new.product_id);
    v_product_ids := array_append(v_product_ids, old.product_id);
  end if;

  perform public.sync_products_successful_rent_count_by_product_ids(v_product_ids);
  return null;
end;
$$;

drop trigger if exists trg_products_successful_rent_count_on_orders on public.rental_orders;
create trigger trg_products_successful_rent_count_on_orders
after update of status on public.rental_orders
for each row execute function public.sync_products_successful_rent_count_from_orders();

drop trigger if exists trg_products_successful_rent_count_on_order_items on public.rental_order_items;
create trigger trg_products_successful_rent_count_on_order_items
after insert or update or delete on public.rental_order_items
for each row execute function public.sync_products_successful_rent_count_from_order_items();

-- 7) Drop obsolete variant relation columns.
-- items.variant_id
alter table if exists public.items
  drop constraint if exists items_variant_id_fkey;

drop index if exists idx_items_variant_id;

alter table if exists public.items
  drop column if exists variant_id;

-- rental_order_items.variant_id + variant_name_snapshot
alter table if exists public.rental_order_items
  drop constraint if exists rental_order_items_variant_id_fkey;

alter table if exists public.rental_order_items
  drop column if exists variant_id;

alter table if exists public.rental_order_items
  drop column if exists variant_name_snapshot;

-- 8) Drop product_variants table after relation columns are removed.
drop table if exists public.product_variants;

-- 9) Recalculate successful_rent_count with product_id-only source.
with counts as (
  select
    roi.product_id,
    count(distinct roi.order_id)::integer as successful_rent_count
  from public.rental_order_items roi
  join public.rental_orders ro
    on ro.id = roi.order_id
   and ro.status = 'COMPLETED'
  where roi.product_id is not null
  group by roi.product_id
)
update public.products p
set successful_rent_count = coalesce(counts.successful_rent_count, 0)
from counts
where p.id = counts.product_id;

update public.products p
set successful_rent_count = 0
where not exists (
  select 1
  from public.rental_order_items roi
  join public.rental_orders ro
    on ro.id = roi.order_id
   and ro.status = 'COMPLETED'
  where roi.product_id = p.id
);

