-- >>> BEGIN 020_owner_admin_role_guard_seed_only.sql

-- Protect owner_admin role assignment at DB level.
-- Runtime/API contexts cannot assign owner_admin or downgrade existing owner_admin users.
-- Seed/migration SQL contexts (postgres/supabase_admin) are allowed.
-- Safe to rerun.

create or replace function public.guard_profiles_owner_admin_seed_only()
returns trigger
language plpgsql
as $$
begin
  if current_user in ('postgres', 'supabase_admin') then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.role = 'owner_admin' then
      raise exception 'OWNER_ADMIN_ROLE_IS_SEED_ONLY';
    end if;

    return new;
  end if;

  if tg_op = 'UPDATE' then
    if old.role = 'owner_admin' and new.role <> 'owner_admin' then
      raise exception 'OWNER_ADMIN_ROLE_IMMUTABLE';
    end if;

    if old.role <> 'owner_admin' and new.role = 'owner_admin' then
      raise exception 'OWNER_ADMIN_ROLE_IS_SEED_ONLY';
    end if;

    return new;
  end if;

  return new;
end
$$;

drop trigger if exists profiles_owner_admin_seed_only_guard on public.profiles;
create trigger profiles_owner_admin_seed_only_guard
before insert or update of role on public.profiles
for each row
execute function public.guard_profiles_owner_admin_seed_only();

-- <<< END 020_owner_admin_role_guard_seed_only.sql

