-- 2) Extend payments to support type EXPENSE and optional procurement trace.
-- 3) Keep branch-scoped RLS/grants aligned with existing schema patterns.

create table if not exists public.procurement_receipts (
  id uuid primary key default gen_random_uuid(),
  branch_id uuid not null references public.branches(id) on delete restrict,
  receipt_code text not null,
  intake_channel text not null default 'MANUAL',
  intake_source_file_name text,
  supplier_name text,
  supplier_phone text,
  note text,
  total_quantity integer not null default 0,
  total_cost_amount numeric(14,2) not null default 0,
  payment_expense_amount numeric(14,2) not null default 0,
  payment_method text,
  payment_note text,
  paid_at timestamptz,
  created_by uuid,
  updated_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint procurement_receipts_receipt_code_not_blank check (btrim(receipt_code) <> ''),
  constraint procurement_receipts_intake_channel_check check (intake_channel in ('MANUAL', 'EXCEL')),
  constraint procurement_receipts_total_quantity_check check (total_quantity >= 0),
  constraint procurement_receipts_total_cost_amount_check check (total_cost_amount >= 0),
  constraint procurement_receipts_payment_expense_amount_check check (payment_expense_amount >= 0),
  constraint procurement_receipts_payment_method_check check (
    payment_method is null or payment_method in ('CASH', 'BANK', 'MOMO')
  )
);

create unique index if not exists procurement_receipts_branch_code_unique
  on public.procurement_receipts (branch_id, lower(receipt_code));
create index if not exists idx_procurement_receipts_branch_created_at
  on public.procurement_receipts (branch_id, created_at desc);

create table if not exists public.procurement_receipt_items (
  id uuid primary key default gen_random_uuid(),
  receipt_id uuid not null references public.procurement_receipts(id) on delete cascade,
  branch_id uuid not null references public.branches(id) on delete restrict,
  product_id uuid references public.products(id) on delete set null,
  product_code_snapshot text,
  product_name_snapshot text,
  quantity integer not null,
  unit_cost_amount numeric(14,2) not null,
  line_total_amount numeric(14,2) not null,
  rent_price_per_day numeric(14,2),
  quick_rent_price numeric(14,2),
  purchase_price numeric(14,2),
  sale_price numeric(14,2),
  category_code_snapshot text,
  is_rentable boolean,
  is_saleable boolean,
  material text,
  gender text,
  description text,
  cover_image_url text,
  item_size text,
  note text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint procurement_receipt_items_quantity_check check (quantity > 0),
  constraint procurement_receipt_items_unit_cost_amount_check check (unit_cost_amount >= 0),
  constraint procurement_receipt_items_line_total_amount_check check (line_total_amount >= 0)
);

create index if not exists idx_procurement_receipt_items_receipt_id
  on public.procurement_receipt_items (receipt_id);
create index if not exists idx_procurement_receipt_items_product_id
  on public.procurement_receipt_items (product_id);
create index if not exists idx_procurement_receipt_items_branch_id
  on public.procurement_receipt_items (branch_id);

alter table if exists public.payments
  add column if not exists procurement_receipt_id uuid references public.procurement_receipts(id) on delete set null;

alter table if exists public.payments
  add column if not exists is_import_order boolean not null default false;

alter table if exists public.payments
  add column if not exists is_initial_capital boolean not null default false;

alter table if exists public.procurement_receipt_items
  alter column product_id drop not null,
  add column if not exists rent_price_per_day numeric(14,2),
  add column if not exists quick_rent_price numeric(14,2),
  add column if not exists purchase_price numeric(14,2),
  add column if not exists sale_price numeric(14,2),
  add column if not exists category_code_snapshot text,
  add column if not exists is_rentable boolean,
  add column if not exists is_saleable boolean,
  add column if not exists material text,
  add column if not exists gender text,
  add column if not exists description text,
  add column if not exists cover_image_url text;

alter table if exists public.payments
  alter column order_id drop not null;

alter table if exists public.payments
  drop constraint if exists payments_type_check;

alter table if exists public.payments
  add constraint payments_type_check
  check (type in ('RENT', 'DEPOSIT', 'FEE', 'REFUND', 'EXPENSE'));

alter table if exists public.payments
  drop constraint if exists payments_target_ref_check;

alter table if exists public.payments
  add constraint payments_target_ref_check
  check (order_id is not null or procurement_receipt_id is not null);

create index if not exists idx_payments_procurement_receipt_id
  on public.payments (procurement_receipt_id);

create index if not exists idx_payments_is_initial_capital
  on public.payments (is_initial_capital);

-- updated_at triggers for new tables
DROP TRIGGER IF EXISTS set_updated_at ON public.procurement_receipts;
create trigger set_updated_at
before update on public.procurement_receipts
for each row execute function public.set_updated_at();

DROP TRIGGER IF EXISTS set_updated_at ON public.procurement_receipt_items;
create trigger set_updated_at
before update on public.procurement_receipt_items
for each row execute function public.set_updated_at();

-- RLS
alter table public.procurement_receipts enable row level security;
alter table public.procurement_receipt_items enable row level security;

drop policy if exists procurement_receipts_branch_select on public.procurement_receipts;
create policy procurement_receipts_branch_select
  on public.procurement_receipts for select
  using (public.can_access_branch(branch_id));

drop policy if exists procurement_receipts_branch_insert on public.procurement_receipts;
create policy procurement_receipts_branch_insert
  on public.procurement_receipts for insert
  with check (public.can_access_branch(branch_id));

drop policy if exists procurement_receipts_branch_update on public.procurement_receipts;
create policy procurement_receipts_branch_update
  on public.procurement_receipts for update
  using (public.can_access_branch(branch_id))
  with check (public.can_access_branch(branch_id));

drop policy if exists procurement_receipts_branch_delete on public.procurement_receipts;
create policy procurement_receipts_branch_delete
  on public.procurement_receipts for delete
  using (public.can_access_branch(branch_id));

drop policy if exists procurement_receipt_items_branch_select on public.procurement_receipt_items;
create policy procurement_receipt_items_branch_select
  on public.procurement_receipt_items for select
  using (public.can_access_branch(branch_id));

drop policy if exists procurement_receipt_items_branch_insert on public.procurement_receipt_items;
create policy procurement_receipt_items_branch_insert
  on public.procurement_receipt_items for insert
  with check (public.can_access_branch(branch_id));

drop policy if exists procurement_receipt_items_branch_update on public.procurement_receipt_items;
create policy procurement_receipt_items_branch_update
  on public.procurement_receipt_items for update
  using (public.can_access_branch(branch_id))
  with check (public.can_access_branch(branch_id));

drop policy if exists procurement_receipt_items_branch_delete on public.procurement_receipt_items;
create policy procurement_receipt_items_branch_delete
  on public.procurement_receipt_items for delete
  using (public.can_access_branch(branch_id));

-- grants
grant select, insert, update, delete on table public.procurement_receipts to authenticated;
grant select, insert, update, delete on table public.procurement_receipt_items to authenticated;

