-- Task 066: makeup module foundation.
-- Scope:
-- - add role `makeup_artist`
-- - add system toggle `is_makeup_module_enabled`
-- - add branch-scoped core table `makeup_events`

-- Keep existing role values safe before applying the new role check.
update public.profiles
set role = case
  when lower(coalesce(role, '')) = 'admin' then 'owner_admin'
  when lower(coalesce(role, '')) in ('owner_admin', 'manager', 'staff', 'accountant', 'makeup_artist', 'customer') then lower(role)
  else 'customer'
end;

alter table if exists public.profiles
  alter column role set default 'customer';

-- Rebuild role constraint (idempotent).
do $$
begin
  if exists (
    select 1
    from pg_constraint
    where conname = 'profiles_role_check'
      and conrelid = 'public.profiles'::regclass
  ) then
    alter table public.profiles
      drop constraint profiles_role_check;
  end if;

  alter table public.profiles
    add constraint profiles_role_check
    check (role in ('owner_admin', 'manager', 'staff', 'accountant', 'makeup_artist', 'customer'));
end $$;

alter table if exists public.system_settings
  add column if not exists is_makeup_module_enabled boolean;

update public.system_settings
set is_makeup_module_enabled = false
where is_makeup_module_enabled is null;

alter table if exists public.system_settings
  alter column is_makeup_module_enabled set default false,
  alter column is_makeup_module_enabled set not null;

create table if not exists public.makeup_events (
  id uuid primary key default gen_random_uuid(),
  branch_id uuid not null references public.branches(id) on delete cascade,
  event_date date not null,
  session_slot text not null,
  artist_profile_id uuid not null references public.profiles(id) on delete restrict,
  customer_id uuid references public.customers(id) on delete set null,
  package_id uuid,
  status text not null default 'BOOKED',
  note text,
  price_amount numeric(14,2) not null default 0,
  cost_amount numeric(14,2) not null default 0,
  is_conflict_warning boolean not null default false,
  conflict_note text,
  created_by uuid references public.profiles(id) on delete set null,
  updated_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint makeup_events_session_slot_check check (session_slot in ('MORNING', 'AFTERNOON', 'EVENING')),
  constraint makeup_events_status_check check (status in ('BOOKED', 'COMPLETED', 'CANCELLED')),
  constraint makeup_events_price_amount_check check (price_amount >= 0),
  constraint makeup_events_cost_amount_check check (cost_amount >= 0)
);

create index if not exists idx_makeup_events_branch_date
  on public.makeup_events (branch_id, event_date);
create index if not exists idx_makeup_events_artist_date
  on public.makeup_events (artist_profile_id, event_date);
create index if not exists idx_makeup_events_customer_date
  on public.makeup_events (customer_id, event_date)
  where customer_id is not null;
create index if not exists idx_makeup_events_branch_slot
  on public.makeup_events (branch_id, event_date, session_slot);

drop trigger if exists set_updated_at on public.makeup_events;
create trigger set_updated_at
  before update on public.makeup_events
  for each row execute function public.set_updated_at();

alter table public.makeup_events enable row level security;

drop policy if exists makeup_events_select on public.makeup_events;
create policy makeup_events_select
  on public.makeup_events for select
  using (public.can_access_branch(branch_id));

drop policy if exists makeup_events_insert on public.makeup_events;
create policy makeup_events_insert
  on public.makeup_events for insert
  with check (
    auth.uid() is not null
    and public.can_access_branch(branch_id)
    and (
      public.current_profile_role() <> 'makeup_artist'
      or artist_profile_id = public.current_profile_id()
    )
  );

drop policy if exists makeup_events_update on public.makeup_events;
create policy makeup_events_update
  on public.makeup_events for update
  using (
    public.can_access_branch(branch_id)
    and (
      public.current_profile_role() <> 'makeup_artist'
      or artist_profile_id = public.current_profile_id()
    )
  )
  with check (
    public.can_access_branch(branch_id)
    and (
      public.current_profile_role() <> 'makeup_artist'
      or artist_profile_id = public.current_profile_id()
    )
  );

drop policy if exists makeup_events_delete on public.makeup_events;
create policy makeup_events_delete
  on public.makeup_events for delete
  using (
    public.can_access_branch(branch_id)
    and public.current_profile_role() in ('owner_admin', 'manager')
  );

grant select, insert, update, delete on table public.makeup_events to authenticated;

