-- >>> BEGIN 030_makeup_event_time_range_and_voice_booking.sql

-- Task 072: product-page makeup booking with voice/text parse + time-range conflict support.
-- Scope:
-- - extend `makeup_events` with real time-range columns
-- - store customer snapshot fields from parsed booking sentence
-- - store source input mode/text metadata for audit/debug

alter table if exists public.makeup_events
  add column if not exists guest_count integer,
  add column if not exists duration_minutes integer,
  add column if not exists start_at timestamptz,
  add column if not exists end_at timestamptz,
  add column if not exists customer_name_snapshot text,
  add column if not exists customer_phone_snapshot text,
  add column if not exists source_input_mode text,
  add column if not exists source_input_text text;

update public.makeup_events
set guest_count = coalesce(guest_count, 1);

update public.makeup_events
set duration_minutes = coalesce(duration_minutes, 80);

update public.makeup_events
set start_at = (
  case coalesce(session_slot, 'MORNING')
    when 'MORNING' then (event_date::timestamp + time '08:00') at time zone 'Asia/Ho_Chi_Minh'
    when 'AFTERNOON' then (event_date::timestamp + time '13:00') at time zone 'Asia/Ho_Chi_Minh'
    else (event_date::timestamp + time '18:00') at time zone 'Asia/Ho_Chi_Minh'
  end
)
where start_at is null;

update public.makeup_events
set end_at = start_at + make_interval(mins => coalesce(duration_minutes, 80))
where end_at is null and start_at is not null;

alter table if exists public.makeup_events
  alter column guest_count set default 1,
  alter column guest_count set not null,
  alter column duration_minutes set default 80,
  alter column duration_minutes set not null,
  alter column start_at set not null,
  alter column end_at set not null;

do $$
begin
  if exists (
    select 1
    from pg_constraint
    where conname = 'makeup_events_guest_count_check'
      and conrelid = 'public.makeup_events'::regclass
  ) then
    alter table public.makeup_events
      drop constraint makeup_events_guest_count_check;
  end if;

  if exists (
    select 1
    from pg_constraint
    where conname = 'makeup_events_duration_minutes_check'
      and conrelid = 'public.makeup_events'::regclass
  ) then
    alter table public.makeup_events
      drop constraint makeup_events_duration_minutes_check;
  end if;

  if exists (
    select 1
    from pg_constraint
    where conname = 'makeup_events_time_range_check'
      and conrelid = 'public.makeup_events'::regclass
  ) then
    alter table public.makeup_events
      drop constraint makeup_events_time_range_check;
  end if;

  if exists (
    select 1
    from pg_constraint
    where conname = 'makeup_events_source_input_mode_check'
      and conrelid = 'public.makeup_events'::regclass
  ) then
    alter table public.makeup_events
      drop constraint makeup_events_source_input_mode_check;
  end if;

  alter table public.makeup_events
    add constraint makeup_events_guest_count_check
    check (guest_count > 0);

  alter table public.makeup_events
    add constraint makeup_events_duration_minutes_check
    check (duration_minutes > 0);

  alter table public.makeup_events
    add constraint makeup_events_time_range_check
    check (end_at > start_at);

  alter table public.makeup_events
    add constraint makeup_events_source_input_mode_check
    check (source_input_mode is null or source_input_mode in ('VOICE', 'TEXT'));
end $$;

create index if not exists idx_makeup_events_branch_start_at
  on public.makeup_events (branch_id, start_at);
create index if not exists idx_makeup_events_artist_start_at
  on public.makeup_events (artist_profile_id, start_at);
create index if not exists idx_makeup_events_customer_phone_snapshot
  on public.makeup_events (branch_id, customer_phone_snapshot)
  where customer_phone_snapshot is not null;

