-- Task 084: makeup inventory catalog core schema.
-- Scope:
-- - add `makeup_inventory_items` table for makeup-only inventory catalog
-- - enforce item -> package and item -> artist mapping
-- - support optional Shopee URL with domain guard

create table if not exists public.makeup_inventory_items (
  id uuid primary key default gen_random_uuid(),
  branch_id uuid not null references public.branches(id) on delete cascade,
  name text not null,
  category text,
  package_id uuid not null references public.makeup_packages(id) on delete restrict,
  artist_profile_id uuid not null references public.profiles(id) on delete restrict,
  shopee_url text,
  note text,
  is_active boolean not null default true,
  created_by uuid references public.profiles(id) on delete set null,
  updated_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint makeup_inventory_items_name_not_blank check (btrim(name) <> ''),
  constraint makeup_inventory_items_shopee_url_check check (
    shopee_url is null
    or lower(shopee_url) ~ '^https?://([a-z0-9-]+\\.)*shopee\\.vn(/.*)?$'
  )
);

create index if not exists idx_makeup_inventory_items_branch_active
  on public.makeup_inventory_items (branch_id, is_active);
