-- Task 085: makeup orders and purchase invoices core schema.
-- Scope:
-- - add makeup purchase invoice tables (header + items)
-- - keep domain isolated from rental procurement tables
-- - support invoice lifecycle + soft-disable (`is_active`)

create table if not exists public.makeup_purchase_invoices (
  id uuid primary key default gen_random_uuid(),
  branch_id uuid not null references public.branches(id) on delete cascade,
  invoice_code text not null,
  invoice_date date not null,
  status text not null default 'DRAFT',
  supplier_name text,
  supplier_phone text,
  note text,
  total_amount numeric(14,2) not null default 0,
  is_active boolean not null default true,
  created_by uuid references public.profiles(id) on delete set null,
  updated_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint makeup_purchase_invoices_code_not_blank check (btrim(invoice_code) <> ''),
  constraint makeup_purchase_invoices_status_check check (
    status in ('DRAFT', 'CONFIRMED', 'PAID', 'CANCELLED')
  ),
  constraint makeup_purchase_invoices_total_amount_check check (total_amount >= 0)
);

create unique index if not exists makeup_purchase_invoices_branch_code_unique
  on public.makeup_purchase_invoices (branch_id, lower(invoice_code));
create index if not exists idx_makeup_purchase_invoices_branch_date
  on public.makeup_purchase_invoices (branch_id, invoice_date desc);
create index if not exists idx_makeup_purchase_invoices_branch_status
  on public.makeup_purchase_invoices (branch_id, status);
create index if not exists idx_makeup_purchase_invoices_branch_active
  on public.makeup_purchase_invoices (branch_id, is_active);

create table if not exists public.makeup_purchase_invoice_items (
  id uuid primary key default gen_random_uuid(),
  invoice_id uuid not null references public.makeup_purchase_invoices(id) on delete cascade,
  inventory_item_id uuid references public.makeup_inventory_items(id) on delete set null,
  item_name text not null,
  quantity integer not null default 1,
  unit_cost_amount numeric(14,2) not null default 0,
  line_total_amount numeric(14,2) not null default 0,
  note text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint makeup_purchase_invoice_items_name_not_blank check (btrim(item_name) <> ''),
  constraint makeup_purchase_invoice_items_quantity_check check (quantity > 0),
  constraint makeup_purchase_invoice_items_unit_cost_check check (unit_cost_amount >= 0),
  constraint makeup_purchase_invoice_items_line_total_check check (line_total_amount >= 0)
);

create index if not exists idx_makeup_purchase_invoice_items_invoice
  on public.makeup_purchase_invoice_items (invoice_id);
create index if not exists idx_makeup_purchase_invoice_items_inventory_item
  on public.makeup_purchase_invoice_items (inventory_item_id)
  where inventory_item_id is not null;

create or replace function public.normalize_makeup_purchase_invoice_item_totals()
returns trigger
language plpgsql
as $$
begin
  new.quantity := greatest(1, coalesce(new.quantity, 1));
  new.unit_cost_amount := greatest(0, coalesce(new.unit_cost_amount, 0));
  new.line_total_amount := round((new.quantity::numeric * new.unit_cost_amount)::numeric, 2);
  return new;
end;
$$;

create or replace function public.sync_makeup_purchase_invoice_total_amount()
returns trigger
language plpgsql
as $$
declare
  target_invoice_id uuid;
begin
  target_invoice_id := coalesce(new.invoice_id, old.invoice_id);

  update public.makeup_purchase_invoices
  set total_amount = coalesce((
      select sum(line_total_amount)
      from public.makeup_purchase_invoice_items
      where invoice_id = target_invoice_id
    ), 0),
    updated_at = now()
  where id = target_invoice_id;

  return null;
end;
$$;

